public sealed class FeatureFlagService
{
    private volatile FeatureFlags _current;
    private readonly ILogger<FeatureFlagService> _logger;

    public FeatureFlagService(
        IOptionsMonitor<FeatureFlags> monitor,
        ILogger<FeatureFlagService> logger)
    {
        _logger = logger;
        _current = monitor.CurrentValue;
        monitor.OnChange(updated =>
        {
            _logger.LogInformation(
                "Feature flags reloaded: NewCheckout={NewCheckout}",
                updated.EnableNewCheckout);
            _current = updated;
        });
    }

    public bool IsEnabled(string name) =>
        name switch
        {
            "NewCheckout" => _current.EnableNewCheckout,
            _ => false
        };
}

public sealed class DynamicLogLevelService : IHostedService
{
    private readonly IOptionsMonitor<LoggerFilterOptions> _monitor;
    private readonly ILoggerFactory _loggerFactory;

    public DynamicLogLevelService(
        IOptionsMonitor<LoggerFilterOptions> monitor,
        ILoggerFactory loggerFactory)
    {
        _monitor = monitor;
        _loggerFactory = loggerFactory;
    }

    public Task StartAsync(CancellationToken ct)
    {
        _monitor.OnChange(_ =>
        {
            // Logging provider may need explicit refresh in custom setups
            _loggerFactory.CreateLogger<DynamicLogLevelService>()
                .LogWarning("Logging filters reloaded from configuration");
        });
        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken ct) => Task.CompletedTask;
}

[Fact]
public async Task FeatureFlag_reload_updates_monitor()
{
    var path = Path.Combine(Path.GetTempPath(), $"appsettings-{Guid.NewGuid()}.json");
    await File.WriteAllTextAsync(path,
        """{"FeatureFlags":{"EnableNewCheckout":false}}""");

    await using var factory = new WebApplicationFactory<Program>()
        .WithWebHostBuilder(b => b.ConfigureAppConfiguration((_, cfg) =>
            cfg.AddJsonFile(path, reloadOnChange: true)));

    var monitor = factory.Services.GetRequiredService<IOptionsMonitor<FeatureFlags>>();
    Assert.False(monitor.CurrentValue.EnableNewCheckout);

    await File.WriteAllTextAsync(path,
        """{"FeatureFlags":{"EnableNewCheckout":true}}""");
    await Task.Delay(500); // file watcher debounce

    Assert.True(monitor.CurrentValue.EnableNewCheckout);
}
